'use strict';
// Server permissions remain authoritative; this UI only exposes allowed controls.
const cabinetCanIssue=['owner','admin'].includes(cabinetUser.role),cabinetRoleNames={owner:'Головний адміністратор',admin:'Адміністратор',user:'Користувач'};
let cabinetUsers=[],cabinetUsersLoading=false,cabinetUsersError='';
async function cabinetRequest(path,payload){const response=await fetch('/api/auth/'+path,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json'}:undefined,body:payload?JSON.stringify(payload):undefined,cache:'no-store'});const value=await response.json();if(!response.ok)throw Error(value.error||'Не вдалося виконати дію.');return value}
function cabinetExpiry(user){return user.expiresAt?new Intl.DateTimeFormat('uk-UA',{dateStyle:'medium',timeStyle:'short'}).format(new Date(user.expiresAt*1000)):'Безстроково'}
function cabinetExpired(user){return user.disabled||(user.expiresAt&&user.expiresAt*1000<=Date.now())}
async function refreshCabinetUsers(){if(!cabinetCanIssue||cabinetUsersLoading)return;cabinetUsersLoading=true;try{cabinetUsers=(await cabinetRequest('users')).users;cabinetUsersError=''}catch(error){cabinetUsersError=error.message}finally{cabinetUsersLoading=false;if(adminMode&&adminTab==='access')render();else if(adminMode)updateCabinetToolbar()}}
function cabinetList(){return `<div class="admin-section-title"><h2>Кабінети</h2><button class="admin-button" data-action="cabinet-create">${icon('plus')}Видати кабінет</button></div><p class="info">Кожен кабінет має окремі картки, операції та файли. Роль адміністратора дозволяє видавати кабінети користувачам.</p>${cabinetUsersError?`<p role="alert">${esc(cabinetUsersError)}</p>`:''}<div class="cabinet-list">${cabinetUsers.filter(user=>user.id!==cabinetUser.id).map(user=>`<article class="cabinet-row"><h3>${esc(user.name||user.login)} <small>· ${esc(user.login)}</small></h3><p>${cabinetRoleNames[user.role]}<br>Доступ: ${cabinetExpiry(user)}</p><p class="cabinet-status ${cabinetExpired(user)?'inactive':''}">${user.disabled?'Доступ вимкнено':cabinetExpired(user)?'Строк доступу завершився':'Активний'}</p><div class="cabinet-actions"><button data-action="cabinet-open" data-id="${user.id}">Відкрити кабінет</button><button data-action="cabinet-edit" data-id="${user.id}">Строк і роль</button><button data-action="cabinet-password" data-id="${user.id}">Новий пароль</button><button data-action="cabinet-toggle" data-id="${user.id}">${user.disabled?'Увімкнути':'Вимкнути'} доступ</button></div></article>`).join('')||`<p class="cabinet-empty">${cabinetUsersLoading?'Завантажуємо кабінети…':'Ще немає виданих кабінетів.'}</p>`}</div>`}
function switchCabinet(id){sessionStorage.setItem('cabinet-workspace:'+cabinetUser.id,id);location.replace('/admin/')}
function updateCabinetToolbar(){const header=document.querySelector('.admin-header');if(!header)return;header.querySelector('.cabinet-tools')?.remove();const tools=document.createElement('div');tools.className='cabinet-tools';tools.innerHTML=`<small>${esc(cabinetUser.login)} · ${cabinetRoleNames[cabinetUser.role]}</small>${cabinetCanIssue?`<select aria-label="Поточний кабінет"><option value="${cabinetUser.id}">Мій кабінет</option>${cabinetUsers.filter(u=>u.id!==cabinetUser.id).map(u=>`<option value="${u.id}" ${cabinetWorkspace===u.id?'selected':''}>${esc(u.login)}</option>`).join('')}</select>`:''}<button data-action="cabinet-own-password">Пароль</button><button data-action="cabinet-logout">Вийти</button>`;tools.querySelector('select')?.addEventListener('change',event=>switchCabinet(event.target.value));header.append(tools)}
if(adminMode&&cabinetCanIssue)adminSections.push(['access','Кабінети','users']);
if(adminMode&&cabinetCanIssue&&location.hash==='#access')adminTab='access';
const adminPageBeforeCabinets=adminPage;adminPage=function(){const template=document.createElement('template');template.innerHTML=adminPageBeforeCabinets();if(adminTab==='access'&&cabinetCanIssue)template.content.querySelector('.admin-content').innerHTML=cabinetList();const note=template.content.querySelector('.admin-note');if(note)note.textContent='Дані цього кабінету зберігаються окремо. Доступ контролюється обліковим записом і строком, який встановив адміністратор.';return template.innerHTML};
const renderBeforeCabinets=render;render=function(){renderBeforeCabinets();if(adminMode)updateCabinetToolbar()};
const settingsBeforeCabinetAccount=appSettingsPage;appSettingsPage=function(){return settingsBeforeCabinetAccount()+`<section class="cabinet-account-footer">Кабінет: ${esc(cabinetUser.login)}<button data-action="cabinet-own-password">Змінити пароль</button><button data-action="cabinet-logout">Вийти з кабінету</button></section>`};
actions['cabinet-logout']=async()=>{await cabinetRequest('logout',{});location.replace((adminMode?'/admin/':'/mono/')+'login.html')};
actions['cabinet-open']=button=>switchCabinet(button.dataset.id);
const cabinetDays=user=>select('Строк доступу','days',[['forever','Безстроково'],[7,'Тиждень'],[30,'Місяць']],user?.expiresAt?(user.expiresAt-Date.now()/1000<=8*86400?7:30):'forever');
const cabinetRole=role=>select('Роль','role',cabinetUser.role==='owner'?[['user','Користувач'],['admin','Адміністратор — може видавати кабінети']]:[['user','Користувач']],role||'user');
const cabinetBaseFormSubmit=document.querySelector('#form').onsubmit;
function cabinetModal(title,html,save,label){
 modal(title,html,null,label);const dialog=document.querySelector('#modal'),form=document.querySelector('#form'),button=form.querySelector(':scope > .primary');button.hidden=false;button.textContent=label;
 const restore=()=>{form.onsubmit=cabinetBaseFormSubmit};dialog.addEventListener('close',restore,{once:true});
 form.onsubmit=async event=>{event.preventDefault();button.disabled=true;try{await save(new FormData(event.target));await refreshCabinetUsers();dialog.close();render()}catch(error){document.querySelector('#error').textContent=error.message}finally{button.disabled=false}};
}
actions['cabinet-create']=()=>cabinetModal('Видати кабінет',field('Ім’я','name','','text','maxlength="80"')+field('Логін','login','','text','required minlength="3" maxlength="64" autocomplete="off" autocapitalize="none"')+field('Пароль','password','','password','required minlength="12" maxlength="256" autocomplete="new-password"')+cabinetRole()+cabinetDays(),async form=>cabinetRequest('users/create',{name:form.get('name'),login:form.get('login'),password:form.get('password'),role:form.get('role'),days:form.get('days')==='forever'?null:Number(form.get('days'))}),'Створити');
actions['cabinet-edit']=button=>{const user=cabinetUsers.find(u=>u.id===button.dataset.id);if(!user)return;cabinetModal('Доступ: '+user.login,cabinetRole(user.role)+cabinetDays(user)+'<p class="form-note">Новий строк рахується від моменту збереження.</p>',async form=>cabinetRequest('users/update',{id:user.id,...(cabinetUser.role==='owner'?{role:form.get('role')}:{}),days:form.get('days')==='forever'?null:Number(form.get('days'))}),'Зберегти')};
actions['cabinet-password']=button=>cabinetModal('Новий пароль користувача',field('Новий пароль','password','','password','required minlength="12" maxlength="256" autocomplete="new-password"'),async form=>cabinetRequest('users/update',{id:button.dataset.id,password:form.get('password')}),'Змінити пароль');
actions['cabinet-toggle']=async button=>{const user=cabinetUsers.find(u=>u.id===button.dataset.id);if(!user)return;await cabinetRequest('users/update',{id:user.id,disabled:!user.disabled});await refreshCabinetUsers()};
actions['cabinet-own-password']=()=>cabinetModal('Змінити пароль',field('Поточний пароль','currentPassword','','password','required autocomplete="current-password"')+field('Новий пароль','password','','password','required minlength="12" maxlength="256" autocomplete="new-password"'),async form=>cabinetRequest('password',{currentPassword:form.get('currentPassword'),password:form.get('password')}),'Зберегти');
if(cabinetCanIssue)refreshCabinetUsers();
